/* Mastery / Original recitations and written problem sets, November 2026.
   Authorial explanations and tasks are independent of linked textbooks.
   No automated grading of prose, no compelled progression or external execution. */
'use strict';
window.MASTERY_LABS = (() => {
  const E = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
  const eng = {};
  const quant = {};
  const L=(id,concept,claim,proof,worked,trap,tasks,source)=>{eng[id]={concept,claim,proof,worked,trap,tasks,source};};
  const M=(id,concept,tasks,source)=>{quant[id]={concept,tasks,source};};
  const Q=(level,title,prompt,hint1,hint2,solution,rubric)=>({level,title,prompt,hints:[hint1,hint2],solution,rubric});

  L('hash','A hash table makes membership questions cheap on average, not in the worst case.',
    'For a Two Sum stream, the map before processing index i contains occurrences strictly before i. This invariant makes distinct indices automatic.',
    'Initially the map is empty and the claim holds. At index i, query target − a[i] before inserting a[i]; a successful lookup finds j<i. Otherwise record a[i] for later queries. Every valid pair (j,i) with j<i will be discovered when its later index arrives. Correctness depends on inserting after the lookup, not before. A standard unordered_map provides expected O(1) average operations, but collisions can make individual operations slow.',
    'Input [3,3], target 6. At i=0 the complement 3 is absent; insert (3→0). At i=1 it is present; return (0,1). If insertion were first, the code could incorrectly use index 0 twice.',
    'Do not confuse expected amortized hash-table behavior with a worst-case time guarantee. For a hostile input or security-sensitive setting, consider ordered maps or robust hashing.',[
      Q('Recitation','Four-sum without counting an element twice','Given [2, 7, 2, 7], find two distinct indices summing to 9. Describe a valid output, the map invariant, and how duplicates affect it.','State what is in the map before each element.','Inspect the first 7: has 2 already been stored?','(0,1) is a valid pair. Before index 1, the table holds 2 from index 0, so the complement 2 is found. The second 2 and 7 are irrelevant once a valid pair is returned. For all-pairs enumeration, store lists of indices rather than one index.','Distinct indices; lookup-before-insert; duplicate policy.'),
      Q('Transfer','Counting subarrays with a target sum','Derive a hash-based O(n) expected-time method to count subarrays whose sum is k. State which cumulative sums must exist before processing the current one.','Define prefix[0]=0; subarray (j,i] sums to prefix[i]−prefix[j].','Count earlier prefixes equal to prefix[i]−k; seed count[0]=1.','Scan prefixes from left to right; for current sum s add count[s−k] to the answer, then increment count[s]. This handles negative numbers unlike a nonnegative-only sliding window. Expected O(n) time and O(n) memory.','Correct prefix identity; correct initialization; negative-number argument.')],
    'MIT 6.006, Hashing; Open Data Structures, Hash Tables.');

  L('twopointer','Sorted order lets us discard whole families of impossible pairs.',
    'In a nondecreasing array, if a[L]+a[R] is too small, no pair (L,j) with j≤R can reach the target. If too large, no pair (i,R) with i≥L can reach it.',
    'For a sum smaller than target, replacing R by any earlier index cannot increase the sum; thus L cannot belong to a feasible pair inside the current interval and is safe to discard. The symmetric argument removes R when the sum is too large. Each iteration strictly shrinks [L,R], so at most n−1 steps occur.',
    'On [1,2,4,7,11] with target 9: 1+11>9, decrement R; 1+7<9, increment L; 2+7=9. The trace proves what was excluded, not just what was found.',
    'Two pointers are not automatically valid on unsorted input. Sorting costs O(n log n) and destroys original positions unless you retain index metadata.',[
      Q('Recitation','Prove a pointer move is safe','For sorted [1,4,5,9,13] and target 10, show the first two pointer updates and justify each mathematically.','Begin with the extreme indices L=0, R=4.','If 1+13>10, every element paired with 13 is at least 1, so 13 is impossible.','First remove 13 because 1+13=14>10. Then 1+9=10, so (1,9) is the solution. A proof of the removed 13 is the essential step.','Correct monotonic argument; exact updates; termination.'),
      Q('Transfer','Closest pair, not exact pair','Give an O(n) scan for the pair whose sum is closest to target in a sorted array. Explain why testing an improved candidate before a pointer move matters.','Record |a[L]+a[R]−T| at every state.','Move L when the sum is too small and R when it is too large.','Keep the best pair seen, then use the usual monotonic move. A move discards pairs that cannot approach T from the appropriate side better than the current boundary candidate. Use a tie-breaking rule, and guard sum overflow.','Objective and tie rule; monotonic reasoning; complexity.')],
    'MIT 6.006, Sorting and sequence problems.');

  L('window','The window is a maintained property, not merely two indices.',
    'With a non-repeating-character window [L,R], the substring contains no duplicate character. When char at R has an occurrence p≥L, set L=max(L,p+1).',
    'Initially the window is empty. If the new character has not appeared in the active window, extending R preserves uniqueness. If it has, deleting the prefix through the most recent duplicate is necessary and sufficient. L never decreases and R visits every character once; this is an amortized O(n) scan.',
    'Scan “abba”: [a]→[ab]→the new b makes L jump to index 2, giving [b]→[ba]. The maximum length is 2, not 3.',
    'The monotonic-pointer proof changes if your condition cannot be restored by removing only elements from the left. For sums with negative integers, ordinary shrinking windows can be invalid.',[
      Q('Recitation','Trace a repeated-character window','Trace L and R while scanning “pwwkew”. State the longest length and one witness substring.','A repeated w invalidates everything through the prior w in the window.','At the second w, L becomes 2; later the longest valid windows have length 3.','Maximum length 3; “wke” or “kew” are witnesses. Maintain each character’s latest index; at R=2, previous w=1 makes L=2. At R=4, the active “wk e” length is 3.','Trace includes index updates; window invariant; valid witness.'),
      Q('Transfer','Minimum window sum under a constraint','For positive integers only, design an O(n) algorithm for the shortest subarray with sum at least S. Explain why positivity is essential.','Grow the right boundary to meet S, then shrink the left while still meeting S.','If a removed positive number makes the sum too small, increasing R is the only way to restore it.','Maintain sum of [L,R], extend R, and while sum≥S update minimum length and subtract a[L++]. Both pointers move monotonically. With negative numbers, the left-shrink decision can be unsafe; prefix sums plus a monotonic deque are a different approach.','Positivity condition; linear amortized proof; no-solution case.')],
    'MIT 6.006, Algorithm design and amortized analysis.');

  L('binary','Binary search is a theorem about a monotone predicate, not a template memorized from memory.',
    'For a predicate false…false,true…true over indices [0,n), maintain an interval [lo,hi) containing the first true index, allowing n as a sentinel for no true indices.',
    'At every iteration, choose mid=lo+(hi−lo)/2. If P(mid), the earliest true index lies in [lo,mid], so set hi=mid; otherwise it lies in [mid+1,hi), so set lo=mid+1. The interval shrinks and preserves the boundary. Eventually lo=hi is the first true position.',
    'For [1,3,3,3,9], first value ≥3: start [0,5), mid=2 true => [0,2); mid=1 true => [0,1); mid=0 false => [1,1). Answer index 1.',
    'Never call a binary-search predicate monotone without proof. The expression (lo+hi)/2 can overflow large integral index types, so use lo+(hi−lo)/2.',[
      Q('Recitation','First feasible production capacity','A machine makes x units/day and must produce ≥100 units in 7 days. Define the monotone predicate for integer x and find the least feasible x.','P(x) means 7*x≥100; its truth value only changes once.','Find the first integer x with x≥100/7.','x=15. For x=14, 98<100; for x=15, 105≥100. Binary search requires an interval known to contain feasibility and carefully bounded integer arithmetic.','Predicate; monotonicity proof; boundary check.'),
      Q('Transfer','Binary-search-on-answer with overflow','Suppose a job takes ceil(work/speed) time units. Minimize integer speed to finish within deadline D. Write a safe predicate and identify possible overflow.','Total time = sum ceil(w_i / speed).','Compute ceil(a/b) as a/b+(a%b!=0) rather than (a+b−1)/b if the sum might overflow.','P(speed) tests whether the sum of integer ceilings is ≤D. Faster speed cannot require more time, so P is monotone. Accumulate using a sufficiently wide integer and stop once sum>D. Answer is the first true speed, or report infeasible.','Monotonicity; safe integer arithmetic; infeasibility.')],
    'MIT 6.006, Binary search and asymptotics.');

  L('stack','A monotonic stack stores candidates that remain useful for future elements.',
    'In a next-greater-element scan, the stack stores indices of unresolved elements in nonincreasing value order. When a larger value arrives, pop indices until the invariant is restored.',
    'Each index is pushed once. An index can be popped once and never returns. Though one iteration might pop many elements, the total operations across the entire scan are O(n). When an index i is popped by j, no earlier j′ between i and j had a larger value, because that would already have popped it.',
    'For [2,1,4,3]: push 2, push 1, then 4 resolves both 1 and 2; 3 remains unresolved. The first greater value after 2 and 1 is 4.',
    'Choose strict or non-strict comparisons intentionally; for duplicates, > versus ≥ changes which indices resolve and may change the expected problem answer.',[
      Q('Recitation','Prove amortized O(n)','A monotonic stack loop contains an inner while loop that might pop n elements. Why is the total algorithm still O(n), not O(n²)?','Charge one unit to each push and each pop.','An element cannot be popped twice after it leaves the stack.','For n inputs, there are exactly n pushes and at most n pops; total stack operations are O(n). A single expensive iteration does not imply every iteration is expensive.','Global accounting; uniqueness of pops; complexity.'),
      Q('Transfer','Histogram largest rectangle','Explain how the previous and next strictly smaller bar positions determine the maximal rectangle that uses a bar of height h as its limiting height.','The width extends until the first smaller bar on each side.','The area for bar i is h_i*(rightSmaller_i−leftSmaller_i−1).','Use a monotonic nondecreasing stack of indices and a trailing sentinel height 0 to flush. When popping i, current j is the next smaller boundary and new stack top is previous smaller boundary. The rectangle area is h[i]*(j−left−1). Define duplicate-height behavior consistently.','Boundary computation; duplicate policy; O(n) proof.')],
    'Open Data Structures, Stacks; MIT 6.006, Data structures.');

  L('trees','Tree recursion is induction on a recursively defined object.',
    'For a binary tree, define height(empty)=0 and height(node)=1+max(height(left),height(right)). Correctness follows by structural induction.',
    'Base: the empty tree has height zero. Inductive step: every longest root-to-leaf path starts by taking exactly one of the children, so its length in nodes equals 1 plus the larger child height. If both recursive calls return correct child heights, the formula returns the correct parent height.',
    'Root 8 with left child 3 and right subtree 10→14: left height 1, right height 2, so root height 3. For a skewed n-node tree, recursion depth reaches n even though total work is O(n).',
    'BST sorted-order properties do not hold for arbitrary binary trees. In C++, deep recursion can overflow the call stack even when an algorithm is mathematically correct.',[
      Q('Recitation','Balance detection in one traversal','Give a linear-time algorithm that both computes subtree heights and rejects nodes whose left/right heights differ by more than 1.','Return a special sentinel when a child subtree is already unbalanced.','A node returns 1+max heights if both children are valid and their difference ≤1.','A postorder function returns -1 for unbalanced, otherwise its height. Propagate -1 immediately; no subtree height is recomputed. O(n) time; O(h) call stack space.','Sentinel meaning; structural proof; complexity.'),
      Q('Transfer','Lowest common ancestor in arbitrary binary tree','Without parent pointers or a BST ordering, explain how recursion identifies the lowest common ancestor of two existing nodes.','A subtree can contain neither, one, or both targets.','If recursive results from both children are nonnull, the current node is their lowest common ancestor.','Return a matching node if current is a target; recurse into both children; if both return nonnull, return current, otherwise return whichever is nonnull. This assumes both targets exist and are distinct; robust behavior if one is missing requires extra bookkeeping.','Existence assumption; recursive case split; O(n) time.')],
    'Open Data Structures, Binary Trees; MIT 6.006, Tree Algorithms.');

  L('graphs','Graph search explores states, but the meaning of “visited” depends on the algorithm.',
    'In unweighted graphs, BFS discovers every vertex at minimum edge distance from the source because the queue processes vertices in nondecreasing distance.',
    'Induct over distance layers. Before any vertex at distance d+1 can be removed, BFS must have processed all discovered vertices at distance d; their outgoing edges discover all reachable candidates at the next layer. Marking on enqueue prevents duplicates and preserves the first shortest discovery. This argument does not extend to arbitrary positive edge weights.',
    'Edges 0→1, 0→2, 1→3, 2→3: BFS queues [0], then [1,2], then discovers 3 with distance 2. It never enqueues 3 twice when visited is set on enqueue.',
    'Do not use BFS for shortest weighted routes when costs differ. Dijkstra requires nonnegative weights; Bellman–Ford handles negative weights and can detect negative cycles.',[
      Q('Recitation','Queue versus stack','On graph 0→1, 0→2, 1→3, 2→3, trace the BFS queue and assign shortest distances from 0.','Start queue [0]; neighbors are discovered at distance 1.','Mark 3 visited at discovery so it appears only once.','dist[0]=0, dist[1]=dist[2]=1, dist[3]=2. The queue evolves [0]→[1,2]→[2,3]→[3]→[]. BFS processes layers, unlike a general DFS stack.','Queue trace; discovery marking; edge counts.'),
      Q('Transfer','0–1 BFS','Edges have weights only 0 or 1. Explain why a deque can compute shortest paths in O(V+E) and specify where each kind of relaxation is enqueued.','A zero-cost edge does not increase the current distance; a one-cost edge does.','Push a zero-weight relaxation to the deque front; a one-weight relaxation to the back.','Maintain tentative distances. For each improved relaxation, push front for weight 0, back for weight 1. Distances are processed in nondecreasing order under this restricted cost set. A careful implementation may process outdated deque entries; storing (vertex,distance) handles stale work.','Weight restriction; deque placement; correctness intuition.')],
    'MIT 6.006, Graph search; CLRS, Shortest paths.');

  L('heap','A binary heap guarantees a local ordering relationship sufficient for fast global extrema.',
    'In a min-heap, every parent key is ≤ its children; therefore the root is a global minimum. The array representation stores children of index i at 2i+1 and 2i+2.',
    'By following parent-child inequalities from any node to the root, the root cannot exceed that node. Inserting at the end and bubbling up repairs at most one path of O(log n) height. Removing the root replaces it with the last element and sifts down at most one path. Constructing a heap bottom-up costs O(n), not O(n log n).',
    'Top-3 of [8,2,7,1,9,4]: maintain a min-heap of at most 3 values. After all inputs, the heap contains {7,8,9}; the root 7 is the smallest currently retained top-3 value.',
    'A heap is not a sorted array. Calling top() gives the extremum, but arbitrary search remains O(n); sorting the retained k answers may require O(k log k).',[
      Q('Recitation','Why a size-k heap?','Find the three largest numbers in [4,8,1,7,5,9] and derive the time complexity for n numbers with a fixed k.','Keep k best so far, with the smallest of them at the root.','If new value exceeds the smallest retained, replace the root; otherwise ignore it.','Result {7,8,9}. Each input performs O(log k) heap work in the worst case, total O(n log k), and O(k) auxiliary memory. This avoids sorting the whole array when k≪n.','Heap invariant; replacement condition; k boundary.'),
      Q('Transfer','Dijkstra priority queue and stale entries','A vertex’s improved distance may be inserted into a heap more than once. Why can a lazy implementation still be correct, and how should it skip stale entries?','Push (candidateDistance,vertex) on every successful relaxation.','When poppedDistance != dist[vertex], ignore the stale entry.','Every successful relaxation creates a candidate; only the current best recorded distance should expand the vertex. For nonnegative weights, the first valid minimum pop finalizes the shortest distance. This is O((V+E)log(V+E)) with duplicates; a Fibonacci heap is not needed for interviews.','Stale-entry handling; nonnegative assumption; complexity.')],
    'Open Data Structures, Binary Heaps; CLRS, Priority Queues.');

  L('cpp-layout','Data layout determines how many cache lines a hot operation touches.',
    'If a hot loop reads only price and quantity, storing them in separate tightly packed arrays may reduce irrelevant memory traffic compared with reading large per-order records.',
    'A cache transfers contiguous lines, not isolated requested fields. With array-of-structures (AoS), each cache line can hold unused fields; structure-of-arrays (SoA) makes the accessed columns dense. But if each operation needs every field, AoS may offer better locality. Measure under the actual access pattern rather than treating SoA as universally superior.',
    'Suppose each order is 64 bytes and a query reads only its 8-byte price. In a simple model with 64-byte cache lines, scanning 1 million AoS records touches about 64 MB. A tightly packed 8-byte price array touches about 8 MB. Real measurements vary with prefetching, alignment, and other fields.',
    'A 64-byte line is an example, not a portable C++ guarantee. False sharing occurs when separate threads repeatedly write distinct variables that occupy the same coherence line.',[
      Q('Recitation','Approximate memory traffic','An array has 250,000 records, each 64 bytes; a query reads only a contiguous 4-byte field. Compare rough scanned byte counts for AoS and a 4-byte SoA column.','AoS touches the cache lines containing each record; count 64 bytes/record in a simple model.','SoA touches only 4 bytes/record in a densely packed column.','AoS ≈16,000,000 bytes; SoA ≈1,000,000 bytes. This is an idealized traffic estimate, not a benchmark result. Caches, prefetching and read coalescing change real behavior.','Numbers; assumptions; distinction between model and measurement.'),
      Q('Transfer','False sharing benchmark design','Two worker threads update different atomic counters. Describe an experiment that tests whether cache-line sharing is responsible for degraded throughput.','Compare counters placed adjacent to those aligned and padded apart.','Keep iteration count, CPU affinity, compiler flags, warm-up and workload identical.','Use a repeated controlled benchmark comparing adjacent atomics with cache-line-padded counters; record p50 and distribution across runs. Avoid a data race by using atomics; padding changes layout but does not by itself prove causation on every architecture.','Controlled variables; correctness; benchmark uncertainty.')],
    'C++ Core Guidelines; Intel optimization manuals; cppreference on hardware interference sizes.');

  L('cpp-concurrency','Correct concurrency needs a happens-before argument, not merely two atomic variables.',
    'A single-producer, single-consumer (SPSC) ring buffer can publish a filled slot using a release store to the head index; the consumer’s acquire load of head establishes visibility of earlier slot writes.',
    'The producer writes data into a slot it exclusively owns, then performs head.store(next, release). The consumer reads head with acquire; if it observes that release (or a later value in its release sequence), the preceding slot write happens-before the consumer reads that slot. This does not permit multiple concurrent producers without an additional claim protocol. Tail indices need their own visibility and reuse discipline.',
    'Capacity 4, head=0, tail=0. Producer writes slot[0]=42 and releases head=1. Consumer acquires head=1, safely reads slot[0], and then advances tail to 1. If head were published before writing the payload, consumer could observe an uninitialized or stale value.',
    'Relaxed atomics make an operation atomic but do not automatically publish unrelated non-atomic payload writes. “Lock-free” also does not mean bounded latency, fair progress, or safe memory reclamation.',[
      Q('Recitation','Reason about release/acquire','Which exact operations are ordered in an SPSC publication path, and why is a release store insufficient without an appropriate consumer acquire?','Identify producer’s ordinary slot write and its release publication store.','Consumer must observe the published head through an acquire (or stronger) operation to establish synchronizes-with.','The producer slot write is sequenced before release store to head. An acquire load of head that reads from the release (or release sequence) synchronizes with that store; then the earlier slot write happens-before the consumer payload read. Merely using atomic indices without matching ordering is not enough.','Named operations; synchronizes-with; distinct owner of the slot.'),
      Q('Transfer','Full and empty ring ambiguity','With head and tail indices in a circular array, explain one way to distinguish a full buffer from an empty buffer, and quantify the effective capacity.','Reserve one array slot so head==tail means empty.','Full occurs when (head+1)%N == tail.','For physical N slots, reserve one: maximum in-flight items N−1. Empty iff head==tail; full iff next(head)==tail. Alternatively use monotonic counters or an explicit state but must prove concurrent correctness.','Precise conditions; capacity; wraparound and overflow policy.')],
    'C++ memory model / cppreference; C++ Concurrency in Action.');

  L('sd-capacity','A capacity estimate is a dimensional proof that your design can carry a plausible workload.',
    'Always annotate units. Average requests/second = requests/day ÷ 86,400 seconds/day. Peaks need a separately stated multiplier; an average alone cannot determine peak capacity.',
    'Start from actions per user per day, active-user count, and read/write mix. Derive QPS, bytes/sec, stored data/year, and headroom. Then identify the service or resource with the tightest constraint. If a design decision changes one assumed quantity, recompute its dependent resource costs. A diagram unsupported by throughput and storage arithmetic is not a capacity plan.',
    'With 2 million active users performing 20 requests/day, average QPS ≈40,000,000/86,400≈463. At a stated 5× peak, plan for ≈2,315 QPS. If each payload is 2 KiB, peak ingress is ≈4.5 MiB/s, before protocol overhead and replication.',
    'Capacity estimates are sensitivity analyses, not guaranteed traffic forecasts. Storage replication, indexing and backup retention can dominate raw payload volume.',[
      Q('Recitation','Derive an order-event log budget','An exchange ingests 5,000 messages/s, average encoded 240 bytes. Estimate daily raw write volume in decimal GB and state two major exclusions.','Multiply messages/s × bytes/message × 86,400 s/day.','Convert bytes to GB with 10⁹, not 2³⁰.','5,000×240×86,400=103,680,000,000 bytes ≈103.68 GB/day. This excludes indexes/metadata, replication, compression variance and backups.','Correct units; arithmetic; missing overhead.'),
      Q('Transfer','Replicas under peak traffic','A read endpoint sees 12,000 peak QPS. One instance safely serves 1,500 QPS, and you require capacity after losing one instance. Estimate minimum number of instances assuming even balancing.','Require (N−1)*1,500≥12,000.','Solve for integer N, then discuss nonuniform traffic and failover.','N≥9. The 9th instance supplies capacity after one failure, but this is a lower bound assuming evenly distributed requests and no other bottleneck.','Failure headroom; ceiling; stated balancing assumptions.')],
    'MIT 6.5840; Designing Data-Intensive Applications.');

  L('sd-reliability','Reliability is about explicit failure behavior and bounded resource use.',
    'A queue absorbs bursts, not sustained overload. If arrival rate λ remains above service rate μ, expected backlog grows roughly at rate λ−μ until the queue fills.',
    'For a deterministic fluid approximation, Q(t)=max(0,Q(0)+(λ−μ)t) during persistent overload. A finite queue has a fill time equal to remaining capacity divided by net arrival rate. After the queue fills, the service must block, reject, shed load, or lose work according to its declared contract. Retry storms can multiply the incoming rate and make overload worse.',
    'If λ=1200 jobs/s, μ=1000 jobs/s, buffer capacity 20,000 and Q(0)=0, it reaches capacity in roughly 20,000/(200)=100 seconds. A “bigger queue” delays failure but does not solve the mismatch.',
    'Do not equate “at least once delivery” with exactly once execution. Reprocessing is normal after crashes; consumer-side idempotency is often essential.',[
      Q('Recitation','Calculate overload time to failure','A queue has 6,000 free slots; arrival=900/s, service=750/s. How long before the queue fills under a constant-rate model?','Backlog grows by arrival minus service each second.','Time=free capacity/(λ−μ).','Net growth 150/s, so approximate fill time 6,000/150=40 seconds. Real burstiness means this is not a strict high-percentile guarantee.','Net rate; units; stochastic caveat.'),
      Q('Transfer','Avoid a retry storm','A downstream service returns 503 to clients. Propose a retry policy and explain how it avoids making a partial outage worse.','Use exponential backoff with randomized jitter and a bounded retry budget.','A circuit breaker or token bucket can limit client-originated retry load.','Use exponential backoff with full jitter, maximum retries/deadline, and a retry budget; limit concurrency, respect Retry-After where valid, and open a circuit on sustained failure. Make operations idempotent when retries can duplicate effects. Observability should track errors, queue length, latency and attempt amplification.','Bounded load; jitter; semantics; monitoring.')],
    'MIT 6.5840; The Google SRE Book.');
  // These five topics already have a long-form faculty seminar. Add distinct recitations without repeating it.
  const R=(id,concept,tasks,source)=>{eng[id]={concept,tasks,source};};
  R('linked','Reason from object identity and pointer lifetime, not from an imagined row of contiguous nodes.',[
    Q('Recitation','Reversing without losing ownership','Given head→4→9→15→null, write the values of prev, cur and next after the first two reversal iterations. State the loop invariant.','Before changing cur->next, save its old value.','After each iteration, prev heads the reversed prefix; cur heads the untouched suffix.','After iteration 1: prev=4, cur=9, next=9 (temporary before advancing). After iteration 2: prev=9→4→null, cur=15. The invariant is that the reversed prefix plus original-order suffix contains all initial nodes without duplication and no suffix link is lost.','Correct pointer states; preservation; termination.'),
    Q('Research extension','Why reference counting can be insufficient','Why can two shared_ptr<Node> links create a memory leak in a cyclic list, and what ownership redesign would you propose?','Shared ownership uses reference counts and cannot collect unreachable cycles by itself.','Represent non-owning backlinks with weak_ptr, or use one owning container.','Two nodes owning one another through shared_ptr retain positive reference counts after outside references disappear; neither destructor executes. Prefer unique ownership of a linear chain where feasible, or weak_ptr for non-owning backedges. A shared_ptr is not a universal memory-safety solution.','Explains cycle; correct ownership model; no dangling references.')],'Open Data Structures: linked lists; ISO C++ Core Guidelines.');
  R('dp','Dynamic programming demands an explicit state, boundary conditions and a complete case partition.',[
    Q('Recitation','Invent a recurrence for minimum coin change','Given coin values {1,3,4}, minimize the number of coins summing to 6 with unlimited copies. Define dp[x], its initial value, and the recurrence; compute dp[6].','dp[x] is minimum count to form total x; dp[0]=0.','For each coin c≤x consider 1+dp[x−c].','dp[x]=min_{c∈{1,3,4},c≤x}(1+dp[x−c]); dp[6]=2 using 3+3. Greedy largest-first gives 4+1+1=3, illustrating why local choice is not enough. Runtime O(amount*numberOfCoins), auxiliary O(amount).','State definition; recurrence; counterexample to greedy.'),
    Q('Transfer','Count ways versus optimize cost','For the same coins, define the number of ordered sequences summing to x. How does the recurrence differ from counting unordered coin combinations?','Ordered count: ways[x]=sum_c ways[x−c], ways[0]=1.','For unordered combinations, process coins in an outer loop and amounts in increasing order.','Ordered sequences treat (1,3) and (3,1) as distinct; ways[x] sums all valid last-coin choices. Unordered combinations use coin-outer, amount-inner 1D DP; processing each denomination once avoids counting permutations repeatedly.','Distinguish combinatorial objects; loop order; base case.')],'MIT 6.006 dynamic programming lectures; CLRS.');
  R('cpp-lifetime','Ownership and object lifetime precede performance claims.',[
    Q('Recitation','Find a dangling view','A function returns std::string_view of a local std::string. Explain the exact lifetime mistake and give two safe alternatives.','string_view does not own characters.','The local std::string is destroyed at function return.','The returned string_view refers to storage owned by the destroyed local string; accessing it violates lifetime requirements. Return std::string by value or return a string_view into storage whose lifetime is guaranteed to exceed the view.','Ownership; lifetime; safe API design.'),
    Q('Transfer','Strong exception guarantee','A vector-like collection grows by allocating a new buffer and moving objects. Describe how to preserve the original contents if an element construction throws.','Allocate new storage first; only commit ownership after successful construction.','For types whose move may throw, copying can preserve the original when copying is available.','Allocate, construct new elements into temporary owned storage, clean up partially constructed elements on failure, and commit the new buffer only after success. If available, use noexcept move or copy to avoid leaving the source partially changed. Full strong guarantee depends on element operations and design.','Two-phase commit; cleanup; stated assumptions.')],'C++ Core Guidelines; cppreference object lifetime and noexcept.');
  R('cpp-book','An exchange is first a deterministic state machine, then an optimized program.',[
    Q('Recitation','Price–time partial fill accounting','Ask queue: A 5@101, B 4@101, C 7@102. Marketable buy quantity 11, max price 102. State fills, remaining book and notional in tick-units.','Execute lowest ask first, FIFO at equal price.','After A and B, 9 units have traded at 101; next take 2 from C at 102.','A fills 5, B fills 4, C fills 2. C remains with 5@102; notional is 5*101+4*101+2*102=1113 tick-units. No fills should occur at prices >102.','Price priority; time priority; remaining volume; exact accounting.'),
    Q('Research extension','Replay determinism','What fields must an order-feed replay preserve for output to be deterministic across runs?','Consider arrival order, order IDs, timestamps, cancellations and trading rules.','Integer ticks and a single sequenced event stream avoid time and floating-point ambiguity.','Specify total event sequence, order IDs, action types, prices in integer ticks, quantities, venue priority model, cancellation semantics, and initial state. Compare the resulting book state and trade log byte-for-byte or by a deterministic hash. Do not rely on wall-clock scheduling for replay order.','Complete event model; deterministic acceptance test; no benchmarking before correctness.')],'Published exchange matching rules; C++ Core Guidelines.');
  R('sd-consistency','A distributed API is a set of observable guarantees under delay, loss, crash and duplication.',[
    Q('Recitation','Ambiguous timeout and retry','The server committed a transfer but the response timed out. What can the client know, and how can it safely retry?','A timeout does not tell you whether the server committed.','Use a stable idempotency key stored atomically with the operation/result.','The client knows neither success nor failure. Retrying with the same key against an authoritative deduplication store must return the original result rather than executing twice. The key and original payload mapping need a defined retention and mismatch policy.','Ambiguous outcome; atomic dedupe; contract.'),
    Q('Transfer','Partition trade-off','Describe the observed behavior of a linearizable inventory read when the leader loses access to the quorum.','What guarantees can still be fulfilled if replicas disagree?','The system can reject/wait rather than invent a stale committed value.','If quorum is required to preserve a linearizable read/write contract, an isolated replica may need to become unavailable or return an explicit stale-read result if the API permits it. It cannot guarantee both availability during every partition and global linearizability.','Concrete contract; partition outcome; no false CAP slogans.')],'MIT 6.5840 replication and consensus; Kleppmann DDIA.');

  M('counting','Build the sample space first; whether order matters determines the combinatorial object.',[
    Q('Recitation','Injective assignments','Five distinct interns are assigned to three distinct desks, with at most one intern per desk. How many assignments exist?','Choose an intern for desk 1, then desk 2, then desk 3.','This is a permutation count, not a subset count.','5*4*3 = 60. The desks are labelled, so an assignment of A to desk 1 and B to desk 2 differs from swapping them.','Sample space; distinctness; ordered vs unordered.'),
    Q('Challenge','Birthday collision approximation','For n independently chosen birthdays among 365 equally likely dates, derive the exact no-collision probability and the approximate scale of n where a collision becomes likely.','Multiply conditional probabilities of avoiding previous birthdays.','log P(no collision) ≈ −n(n−1)/(2*365) for n not too large.','P(no collision)=product_{j=0}^{n−1}(1−j/365) for n≤365. Using log(1−x)≈−x gives approx exp(−n(n−1)/730), which falls below 1/2 near n≈23; independence/equiprobability are modeling assumptions.','Exact product; approximation regime; assumptions.')],'Blitzstein–Hwang, Introduction to Probability, counting and birthday problem.');
  M('algebra','An equation solves a model only after the state variables and boundary conditions are defined.',[
    Q('Recitation','Solve a hitting-time recurrence','Let E be the expected steps until success, with success probability p each independent attempt. Derive E from a first-step equation.','Either succeed in one step or take one step and restart.','E=1+(1−p)E.','E=1/p for p>0. The first-step equation is valid because failures restart the experiment independently with the same expected remaining time.','Condition on first outcome; solve; p=0 case.'),
    Q('Transfer','Check spurious solutions','Solve x^2=4, then solve sqrt(x+2)=x. Explain why each candidate must be checked in the original equation.','Squaring is not an equivalence if sign restrictions are lost.','For the radical equation, x≥0 and x+2=x^2.','x²=4 has x=±2. For sqrt(x+2)=x, squaring gives x=2 or x=−1; only x=2 meets x≥0 and verifies 2=2.','Domain; transformed equation; original check.')],'Zhou, A Practical Guide to Quantitative Finance Interviews, algebra.');
  M('calculus','Derivatives express local sensitivity, not necessarily global optimality.',[
    Q('Recitation','Optimal quote offset in a toy model','Let revenue f(δ)=δ A exp(−kδ) for A,k>0 and δ≥0. Find the optimal quote offset and justify the maximum.','Differentiate using the product rule.','f′(δ)=A exp(−kδ)(1−kδ).','The unique interior maximizer is δ*=1/k. f′ positive below 1/k and negative above; f(0)=0 and f(δ)→0 as δ→∞. This is a simplified expected-revenue function, not a complete market-making optimizer.','Derivative; sign analysis; assumptions.'),
    Q('Transfer','Taylor error','Approximate exp(x) near x=0 with 1+x+x²/2. Explain what the omitted remainder means at x=0.1.','Taylor formula needs a higher derivative bound on the interval.','For some ξ between 0 and 0.1, remainder = exp(ξ)*x³/6.','At x=0.1, absolute error ≤ exp(0.1)*(0.1)^3/6≈0.0001842. Naming and bounding the remainder distinguishes rigorous approximation from guesswork.','Remainder form; interval; valid bound.')],'Zhou, Calculus; standard Taylor theorem.');
  M('matrix-basics','Matrices encode transformations and constraints; a numerical solution is not only a symbolic inverse.',[
    Q('Recitation','Singular regression design','Let X have two identical columns. Why cannot X^T X be invertible, and what does this mean for OLS coefficients?','There exists a nonzero vector v with Xv=0.','Then v^T X^T X v=||Xv||²=0.','X has rank deficiency; X^T X is singular and OLS coefficients are not uniquely identifiable. Some predictions Xβ can still be unique. Use QR/SVD or regularization with explicitly stated objectives.','Rank; normal-equations issue; practical alternative.'),
    Q('Transfer','Positive semidefinite covariance','Prove that a valid covariance matrix Σ satisfies a^TΣa≥0 for every vector a.','Represent a linear combination Z=a^T X.','a^TΣa = Var(a^T X).','For any finite-second-moment random vector X, Var(a^T X)=a^T Cov(X)a≥0 because variance is nonnegative. Thus covariance matrices are positive semidefinite, not necessarily positive definite.','Quadratic form; variance; PSD not PD.')],'Zhou, Linear Algebra; Blitzstein–Hwang covariance.');
  M('expected-value','Expectation is linear even when outcomes are dependent.',[
    Q('Recitation','Expected fixed points','A random permutation of n distinct objects is uniformly chosen. How many objects remain in their original positions on average?','Define I_i=1 if position i is fixed, else 0.','E[I_i]=1/n; E[sum I_i]=sum E[I_i].','Expected number of fixed points is n*(1/n)=1, for every n≥1. Independence among I_i is not needed; in fact the indicators are generally dependent.','Indicator definition; uniform symmetry; linearity.'),
    Q('Challenge','Expected unseen coupons','After m independent draws uniformly among n types, how many distinct types do you expect to have seen?','For each type define I_i=1 if observed at least once.','P(type i never appears)=(1−1/n)^m.','E[distinct]=n[1−(1−1/n)^m], by summing type indicators. The events of observing different types need not be independent.','Correct indicator; complement probability; n and m boundary cases.')],'Blitzstein–Hwang, indicators and expectation.');
  M('conditional','Conditioning changes the sample space; it does not necessarily change the mechanism.',[
    Q('Recitation','Two dice under a condition','Two fair dice are rolled. Given that their sum is 7, what is the probability the first die shows 3?','List the ordered outcomes whose sum is 7.','There are six such outcomes, each equally likely under the condition.','P(first=3 | sum=7)=1/6 because the six possibilities are (1,6),(2,5),(3,4),(4,3),(5,2),(6,1). The first-die value is no longer uniformly distributed over all six independent of the sum.','Conditional sample space; ordered outcomes; ratio.'),
    Q('Transfer','Simpson’s paradox','Two treatments appear better/worse depending on whether groups are combined. Explain how confounding group sizes change a pooled rate.','Write the pooled rate as a weighted average of subgroup rates.','The weights can differ between treatments and make the aggregate reverse subgroup comparisons.','Pooled outcome rates are weighted by each treatment’s case mix. Unequal proportions of easy and difficult cases can reverse a within-group comparison. Correct causal inference requires defining adjustment assumptions, not simply trusting the overall ratio.','Correct weighted-average argument; recognizes confounding.')],'Blitzstein–Hwang, conditional probability.');
  M('bayes','Posterior odds equal prior odds multiplied by the likelihood ratio.',[
    Q('Recitation','Testing a rare condition','Prevalence=1%, sensitivity=90%, false-positive rate=5%. Find P(condition | positive) and interpret it.','Compute true-positive mass and false-positive mass per person.','Bayes numerator=0.01*0.90; denominator adds 0.99*0.05.','0.009/(0.009+0.0495)=0.153846≈15.4%. Most positive results can be false positives when the base rate is small.','Base rate; conditional rates; posterior interpretation.'),
    Q('Challenge','Two conditional signals','Given prior odds 1:9 and independent signals conditional on the hidden state, each with likelihood ratio 3, find posterior odds after both. State the independence caveat.','Multiply odds by each LR if the signals are conditionally independent given both competing hypotheses.','Prior odds 1/9; after two signals odds 1/9*3*3=1.','Posterior odds 1:1, giving probability 1/2. If signals are correlated conditional on the state, multiplying marginal likelihood ratios double-counts evidence.','Odds conversion; LR multiplication; conditional independence.')],'Blitzstein–Hwang, Bayes’ theorem.');
  M('recursive','The first-step method requires states that preserve all information relevant to the future.',[
    Q('Recitation','Consecutive heads waiting time','Let E0 be expected remaining fair-coin flips with no current head run, E1 after one head. Write and solve the equations for first HH.','From E0, H sends to E1 and T restarts E0.','E0=1+0.5E1+0.5E0; E1=1+0.5*0+0.5E0.','Solve: E0=2+E1 and E1=1+0.5E0; hence E0=6 and E1=4. This is not 4 despite P(HH in two flips)=1/4, because patterns overlap.','States; equations; solution; overlap.'),
    Q('Transfer','HT waiting time','Model first occurrence of HT with states E0 (no trailing H) and E1 (trailing H). Why is expected waiting time 4, unlike HH?','After H at E1, another H leaves you in E1 rather than resetting to E0.','E0=1+0.5E1+0.5E0; E1=1+0.5E1.','E1=2; E0=2+E1=4. The state transition differs because consecutive H preserves the useful prefix H for HT.','State transitions; equations; difference from HH.')],'Blitzstein–Hwang, Markov chains and waiting times; Zhou stochastic processes.');
  M('distributions','A distribution is a model for a random quantity, not a set of parameters to memorize.',[
    Q('Recitation','Poisson from a rate','If market events form a homogeneous Poisson process at 3 per minute, compute P(no events in 20 seconds).','Convert 20 seconds to 1/3 minute, so expected count is λt=1.','P(N(t)=0)=exp(−λt).','P(0)=exp(−1)≈0.3679. Units are crucial. This assumes stationary independent increments and the Poisson model.','Unit conversion; distribution equation; assumption.'),
    Q('Transfer','Exponential waiting time memorylessness','If time to next event is Exp(λ), find P(T>s+t | T>s) and say what it means.','Apply conditional probability to survival functions.','P(T>u)=exp(−λu).','P(T>s+t|T>s)=exp(−λ(s+t))/exp(−λs)=exp(−λt). Waiting an additional t is no more/less likely after already waiting s, under a homogeneous Poisson model.','Conditional survival; assumption; interpretation.')],'Zhou, Probability Distributions; Blitzstein–Hwang.');
  M('regression','Regression is projection in a specified model, not proof of causality.',[
    Q('Recitation','OLS slope from first principles','For observations (x,y)=(0,1),(1,3),(2,5), derive the slope and intercept for least squares by inspection or normal equations.','The points lie exactly on a line; test y=1+2x.','Any line with zero residual sum of squares is least-squares optimal.','Intercept 1, slope 2, residual sum of squares 0. This is an exact fit for three points but not evidence that x causes y or that the model generalizes.','Fit; residual; causal caveat.'),
    Q('Transfer','Data leakage in time series','Why does random train/test splitting of strongly autocorrelated market observations often overstate backtest performance?','Nearby observations can share information or nearly duplicate regimes.','Choose train data strictly earlier than the validation period and simulate feature availability at decision time.','A random split can put highly related periods on both sides and expose future-regime information. Use time-ordered or purged/embargoed validation appropriate to label horizons, realistic costs, and leak-free feature construction.','Leakage mechanism; time-aware split; costs.')],'Zhou, Regression and OLS; quantitative research principles.');
  M('orderbook','Order-book execution is a conservation law governed by a venue’s matching priority rules.',[
    Q('Recitation','An incoming order walking the book','Asks: 4@100, then 3@101. Incoming buy limit 6@101. State fills, unfilled resting quantities, VWAP in tick units, and the book’s next best ask.','Match lowest asks first; fill up to quantity 6.','Take 4@100 then 2@101.','Total 6 filled; second ask retains 1@101; VWAP=(4*100+2*101)/6=100.333... ticks. Highest allowed price was 101, not a promise to fill at 101.','Fill conservation; priority; VWAP.'),
    Q('Challenge','Queue position versus visible depth','Why does a quote at the best bid not guarantee a fill when a sell market order arrives?','Other resting bids may be ahead of your order at the same price.','Cancellation and venue priority rules determine how much volume reaches your queue position.','Best-price presence alone says nothing about queue rank. Earlier orders at the same price may consume all incoming liquidity. Some venues use pro rata or other priority rather than FIFO; state venue rules and how hidden liquidity may change executions.','Queue order; partial execution; venue caveat.')],'Avellaneda–Stoikov; published exchange matching rules.');
  M('avellaneda-stoikov','A market-making model is useful only when its risk and execution assumptions remain visible.',[
    Q('Recitation','Inventory-adjusted reservation price','Given S=100, q=5, γ=0.1, σ=2 price units/sqrt(time), remaining τ=0.5, compute r=S−qγσ²τ. Interpret the sign.','Compute σ²=4 and qγσ²τ.','Positive inventory should lower reservation price.','Adjustment=5*0.1*4*0.5=1, hence r=99. A long dealer lowers the center of quotations to encourage selling and discourage further inventory accumulation. Units and horizon are model-specific.','Arithmetic; units; inventory intuition.'),
    Q('Research extension','Price-risk versus fill-risk tradeoff','Explain why raising a quote’s distance from mid may reduce adverse inventory risk yet reduce expected execution revenue.','In the stylized model, fill intensity λ(δ)=A exp(−kδ) decays with distance δ.','A larger spread earns more per fill but fills less frequently; inventory penalty additionally depends on q, γ, σ and τ.','Expected spread capture is not monotone in quote distance: δ increases per-fill revenue but decreases trade intensity. Risk-adjusted optimal quotes balance inventory exposure, fills and the exponential utility objective. Actual fee, tick, queue and informed-flow effects are omitted in the simple model.','Fill-intensity mechanism; inventory penalty; model limits.')],'Avellaneda and Stoikov (2008), High-frequency trading in a limit order book.');
  M('inference','A confidence interval is a procedure with frequentist coverage under repeated sampling, not a probability distribution on a fixed parameter.',[
    Q('Recitation','Standard error of a mean','IID returns have sample standard deviation s=0.02 and n=100. Estimate the standard error of sample mean and explain the IID assumption.','SE≈s/sqrt(n).','sqrt(100)=10.','Estimated SE=0.002. Serial correlation or changing variance can invalidate the IID-based estimate; consider HAC or block-bootstrap methods for time series.','Arithmetic; sampling assumption; return dependence.'),
    Q('Transfer','Multiple comparisons','A researcher tests 200 independent null trading rules at nominal 5% significance. How many false positives are expected?','Define an indicator for each false rejection.','E[false positives]=200*0.05.','Expected 10 false positives under the null; the count is not proof of ten profitable strategies. Dependence may alter the distribution but not the expectation if each marginal size remains 5%. Adjust for selection and conduct honest out-of-sample testing.','Linearity; distinction expectation/probability; selection caveat.')],'Blitzstein–Hwang, statistical inference; research methodology.');
  M('variance','Variance measures squared dispersion and requires covariance terms when combining risks.',[
    Q('Recitation','Portfolio variance','Two assets each have variance 4 and covariance 1. What is the variance of their equally weighted average (X+Y)/2?','Var(aX+bY)=a²Var(X)+b²Var(Y)+2abCov(X,Y).','Set a=b=1/2.','Variance=1+1+0.5=2.5. Omitting covariance gives 2, which underestimates risk with positive covariance.','Weights; covariance; arithmetic.'),
    Q('Challenge','Antithetic Monte Carlo','Suppose U~Uniform(0,1). Why can averaging f(U) and f(1−U) reduce simulation variance for increasing f?','f(U) increases while f(1−U) decreases as U grows.','Their covariance is often nonpositive for monotone f, reducing variance of the pair average.','The two terms have the same marginal expectation; the covariance may be negative for increasing f. Then Var((f(U)+f(1−U))/2)=(Var(f(U))+Cov(f(U),f(1−U)))/2, smaller than a pair of independent draws when covariance<0. This is not guaranteed for arbitrary f.','Unbiasedness; covariance; monotonic assumption.')],'Blitzstein–Hwang, variance and covariance.');

  const KEY='mastery-recitation-drafts-v1';
  let answers={};
  try { const stored=JSON.parse(localStorage.getItem(KEY)||'{}'); if(stored&&typeof stored==='object'&&!Array.isArray(stored)) answers=stored; } catch {}
  const keyFor=(domain,id,n)=>domain+':'+id+':'+n;
  const validKey=k=>/^(engineering|mathematics):[a-z0-9-]+:[0-2]$/.test(k);
  const exportAnswers=()=>({...answers});
  const restoreAnswers=(data)=>{
    if(!data||typeof data!=='object'||Array.isArray(data))return;
    const next={};for(const [k,v] of Object.entries(data)){
      const parts=k.split(':');if(!validKey(k)||typeof v!=='string'||v.length>50000)continue;
      if(!(parts[0]==='engineering'?eng[parts[1]]:quant[parts[1]]))continue;
      next[k]=v.slice(0,12000);
    }
    answers=next;try{localStorage.setItem(KEY,JSON.stringify(answers));}catch{}
  };
  const labCard=(domain,id,t,i)=>{
    const key=keyFor(domain,id,i);
    return `<article class="recitation-problem" data-recitation-problem="${E(key)}">
      <p class="recitation-label">${E(t.level)} · ${String(i+1).padStart(2,'0')}</p>
      <h4>${E(t.title)}</h4><p class="recitation-prompt">${E(t.prompt)}</p>
      <label class="recitation-answer-label" for="lab-${E(domain)}-${E(id)}-${i}">Your solution, proof or design argument</label>
      <textarea id="lab-${E(domain)}-${E(id)}-${i}" data-recitation-answer="${E(key)}" rows="5" spellcheck="true" placeholder="Work through the reasoning. Name the invariant or assumptions; write intermediate steps; check a boundary case.">${E(answers[key]||'')}</textarea>
      <p class="recitation-small">Saved automatically in this browser. The written answer is not automatically graded.</p>
      <div class="recitation-disclosures"><details><summary>Hint 1</summary><p>${E(t.hints[0])}</p></details>
      <details><summary>Hint 2</summary><p>${E(t.hints[1])}</p></details>
      <details class="recitation-solution"><summary>Worked solution & reasoning</summary><p>${E(t.solution)}</p><h5>Check your reasoning against</h5><p>${E(t.rubric)}</p></details></div>
    </article>`;
  };
  const render=(domain,id)=>{
    const d=domain==='engineering'?eng[id]:quant[id];if(!d)return '';
    const extension=domain==='engineering'&&d.claim?`<div class="recitation-lecture">
      <p class="recitation-label">Additional lecture · analysis</p><h3>${E(d.concept)}</h3>
      <h4>Proposition and assumptions</h4><p>${E(d.claim)}</p>
      <h4>Correctness / derivation</h4><p>${E(d.proof)}</p>
      <h4>Worked example</h4><p>${E(d.worked)}</p>
      <h4>When the argument fails</h4><p>${E(d.trap)}</p></div>`:'';
    return `<div class="academic-recitation" id="academic-recitation-${E(domain)}" data-lab-domain="${E(domain)}" data-lab-topic="${E(id)}">
      ${extension}<div class="recitation-heading"><p class="recitation-label">LECTURE COMPANION · INDEPENDENT REASONING</p>
      <h3>Recitation & problem set</h3><p>${E(d.concept)}</p>
      <p class="recitation-instructions">Attempt each problem before opening hints. Reveal the solution after writing your reasoning, then compare against the criteria. No question blocks the next lecture.</p></div>
      ${d.tasks.map((t,i)=>labCard(domain,id,t,i)).join('')}
      <p class="recitation-source">Further study: ${E(d.source||'See the main lecture reading references.')} These are independently written exercises, not reproduced course worksheets.</p>
    </div>`;
  };
  document.addEventListener('input',ev=>{
    const el=ev.target;if(!el.matches?.('[data-recitation-answer]'))return;
    const id=el.dataset.recitationAnswer;
    if(!validKey(id))return;
    answers[id]=String(el.value).slice(0,12000);
    try{localStorage.setItem(KEY,JSON.stringify(answers));}catch{}
  });
  return {render,exportAnswers,restoreAnswers,has:(domain,id)=>!!(domain==='engineering'?eng[id]:quant[id]),
    audit:()=>({engineering:Object.keys(eng).length,mathAndQuant:Object.keys(quant).length,
      problems:Object.values(eng).reduce((s,l)=>s+l.tasks.length,0)+Object.values(quant).reduce((s,l)=>s+l.tasks.length,0)})};
})();